<?php

declare(strict_types=1);

use EventMenu\Core\Auth;
use EventMenu\Core\Security;
use EventMenu\Services\OperatingUnitService;
use EventMenu\Services\ProductConfigurationService;
use EventMenu\Support\OperationalDiagnostics;

Auth::requirePermission('production.manage');$tenantId=em_require_tenant();
try{$unit=(new OperatingUnitService())->requireCurrent();}catch(Throwable$e){$safe=OperationalDiagnostics::userFacing($e,'Não foi possível carregar a produção desta unidade.','web.production.unit');em_header('Produção','production');?><div class="alert error"><?= Security::e($safe['message']) ?></div><?php em_footer();return;}$unitId=(int)$unit['id'];$config=new ProductConfigurationService();
if($_SERVER['REQUEST_METHOD']==='POST'){em_post_csrf();$action=(string)($_POST['action']??'');try{if($action==='station-save'){$id=$config->saveStation($_POST);em_flash('ok','Setor de produção salvo em '.$unit['name'].'.');}else throw new RuntimeException('Ação inválida.');}catch(Throwable$e){$safe=OperationalDiagnostics::userFacing($e,'Não foi possível salvar este setor de produção.','web.production.save',['action'=>$action]);em_flash('error',$safe['message']);}em_go('production');}
$stations=$config->stations($tenantId,false,$unitId);
$productsStmt=$pdo->prepare('SELECT p.id,p.name,p.sku,COALESCE(upp.production_enabled,pp.production_enabled,0) production_enabled,COALESCE(upp.prep_minutes,pp.prep_minutes) prep_minutes,ps.name station_name,ps.station_type FROM products p LEFT JOIN product_unit_production_profiles upp ON upp.product_id=p.id AND upp.tenant_id=p.tenant_id AND upp.unit_id=? LEFT JOIN product_production_profiles pp ON pp.product_id=p.id AND pp.tenant_id=p.tenant_id LEFT JOIN production_stations ps ON ps.id=COALESCE(upp.station_id,pp.station_id) WHERE p.tenant_id=? ORDER BY p.active DESC,p.name');$productsStmt->execute([$unitId,$tenantId]);$products=$productsStmt->fetchAll();
$printStmt=$pdo->prepare('SELECT pr.*,ps.name station_name,u.name user_name FROM production_prints pr JOIN production_stations ps ON ps.id=pr.station_id LEFT JOIN users u ON u.id=pr.printed_by WHERE pr.tenant_id=? AND pr.unit_id=? ORDER BY pr.id DESC LIMIT 80');$printStmt->execute([$tenantId,$unitId]);$prints=$printStmt->fetchAll();$activeStations=count(array_filter($stations,fn($s)=>(int)$s['active']===1));$routed=count(array_filter($products,fn($p)=>(int)($p['production_enabled']??0)===1));$stationLabels=['kitchen'=>'Cozinha','bar'=>'Bar','grill'=>'Chapa / grelha','fryer'=>'Fritadeira','dessert'=>'Sobremesa','assembly'=>'Montagem / saída','other'=>'Outro'];$printerLabels=['manual'=>'Manual','auto'=>'Automática','none'=>'Não imprimir'];$printTypeLabels=['auto'=>'Automática','manual'=>'Manual','reprint'=>'Reimpressão'];
em_header('Produção','production');
?>
<section class="page-hero"><div><span class="eyebrow">PRODUÇÃO · <?= Security::e(mb_strtoupper($unit['name'])) ?></span><h2>Setores de preparo</h2><p>Organize cozinha, bar, chapa, fritadeira, sobremesas e montagem. Cada produto pode seguir para o setor correto automaticamente.</p></div><div class="actions"><a class="button primary" href="<?= Security::e(app_url('?route=kitchen')) ?>">Abrir cozinha</a></div></section>
<section class="grid dashboard-metrics"><div class="card metric"><span class="muted">Setores ativos</span><strong><?= $activeStations ?></strong></div><div class="card metric"><span class="muted">Produtos com preparo</span><strong><?= $routed ?></strong></div><div class="card metric"><span class="muted">Produtos sem setor</span><strong><?= max(0,count($products)-$routed) ?></strong></div><div class="card metric"><span class="muted">Unidade</span><strong style="font-size:18px"><?= Security::e($unit['name']) ?></strong></div></section>
<div class="grid" style="grid-template-columns:minmax(320px,1fr) minmax(0,2fr)"><section class="card"><span class="eyebrow">NOVO SETOR</span><h2>Configurar setor</h2><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="station-save"><label>Nome<input name="name" required placeholder="Ex.: Chapa"></label><label>Tipo<select name="station_type"><option value="kitchen">Cozinha</option><option value="bar">Bar</option><option value="grill">Chapa / grelha</option><option value="fryer">Fritadeira</option><option value="dessert">Sobremesa</option><option value="assembly">Montagem / saída</option><option value="other">Outro</option></select></label><label>Tempo esperado de preparo<input type="number" name="sla_minutes" min="1" max="240" value="15"><small>Em minutos.</small></label><label>Impressão<select name="printer_mode"><option value="manual">Manual</option><option value="auto">Automática</option><option value="none">Não imprimir</option></select></label><label class="checkbox"><input type="checkbox" name="active" checked> Setor ativo</label><details class="technical-details span-2"><summary>Configurações avançadas</summary><div class="form-grid" style="margin-top:10px"><label>Código interno<input name="code" required placeholder="CHAPA"></label><label>Destino da impressora<input name="printer_target" placeholder="Ex.: cozinha-01"></label><label>Ordem de exibição<input type="number" name="sort_order" value="0"></label></div></details><button class="primary span-2">Salvar setor</button></form></section><section class="card"><div class="section-head"><div><span class="eyebrow">SETORES</span><h2>Preparo em <?= Security::e($unit['name']) ?></h2></div><span class="badge"><?= count($stations) ?></span></div><?php if(!$stations):?><div class="alert">Cadastre pelo menos um setor antes de direcionar produtos para produção.</div><?php else:?><div class="table-wrap"><table class="table"><thead><tr><th>Setor</th><th>Tipo</th><th>Tempo esperado</th><th>Impressão</th><th>Situação</th><th></th></tr></thead><tbody><?php foreach($stations as$s):?><tr><td><strong><?= Security::e($s['name']) ?></strong></td><td><?= Security::e($stationLabels[$s['station_type']]??'Outro') ?></td><td><?= (int)$s['sla_minutes'] ?> min</td><td><?= Security::e($printerLabels[$s['printer_mode']]??'Manual') ?></td><td><span class="status-pill <?= $s['active']?'active':'cancelled' ?>"><?= $s['active']?'Ativo':'Inativo' ?></span></td><td><details><summary class="button secondary compact">Editar</summary><form method="post" class="form-grid" style="margin-top:12px;min-width:280px"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="station-save"><input type="hidden" name="id" value="<?= (int)$s['id'] ?>"><label class="span-2">Nome<input name="name" value="<?= Security::e($s['name']) ?>" required></label><label>Tipo<select name="station_type"><?php foreach($stationLabels as$v=>$l):?><option value="<?= $v ?>"<?= em_selected($s['station_type'],$v) ?>><?= Security::e($l) ?></option><?php endforeach;?></select></label><label>Tempo esperado<input type="number" name="sla_minutes" value="<?= (int)$s['sla_minutes'] ?>"></label><label>Impressão<select name="printer_mode"><?php foreach($printerLabels as$v=>$l):?><option value="<?= $v ?>"<?= em_selected($s['printer_mode'],$v) ?>><?= Security::e($l) ?></option><?php endforeach;?></select></label><label class="checkbox"><input type="checkbox" name="active"<?= em_checked($s['active']) ?>> Ativo</label><details class="technical-details span-2"><summary>Configurações avançadas</summary><div class="form-grid" style="margin-top:10px"><label>Código interno<input name="code" value="<?= Security::e($s['code']) ?>" required></label><label>Destino da impressora<input name="printer_target" value="<?= Security::e($s['printer_target']??'') ?>"></label><label>Ordem<input type="number" name="sort_order" value="<?= (int)$s['sort_order'] ?>"></label></div></details><button class="primary span-2">Salvar</button></form></details></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section></div>
<section class="card" style="margin-top:18px"><div class="section-head"><div><span class="eyebrow">PRODUTOS</span><h2>Para onde cada produto vai</h2></div><span class="muted">A ficha técnica e os adicionais continuam os mesmos; o setor pode variar por unidade.</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Produto</th><th>Preparo</th><th>Setor</th><th>Tempo</th><th></th></tr></thead><tbody><?php foreach($products as$p):?><tr><td><strong><?= Security::e($p['name']) ?></strong><?php if($p['sku']):?><br><span class="muted"><?= Security::e($p['sku']) ?></span><?php endif;?></td><td><span class="status-pill <?= !empty($p['production_enabled'])?'active':'cancelled' ?>"><?= !empty($p['production_enabled'])?'Enviado para preparo':'Sem preparo configurado' ?></span></td><td><?= Security::e($p['station_name']??'—') ?></td><td><?= $p['prep_minutes']?((int)$p['prep_minutes'].' min'):'Tempo do setor' ?></td><td><a class="button secondary" href="<?= Security::e(app_url('?route=product-config&product_id='.(int)$p['id'])) ?>">Configurar</a></td></tr><?php endforeach;?></tbody></table></div></section>
<details class="technical-details" style="margin-top:18px"><summary>Histórico de impressão</summary><section class="card"><p class="muted">Informação para conferência e suporte. Não é necessária para o preparo normal.</p><?php if(!$prints):?><p class="muted">Nenhuma impressão registrada nesta unidade.</p><?php else:?><div class="table-wrap"><table class="table"><thead><tr><th>Data</th><th>Pedido</th><th>Setor</th><th>Tipo</th><th>Usuário</th><th>Motivo</th></tr></thead><tbody><?php foreach($prints as$pr):?><tr><td><?= Security::e($pr['created_at']) ?></td><td>#<?= (int)$pr['order_id'] ?></td><td><?= Security::e($pr['station_name']) ?></td><td><?= Security::e($printTypeLabels[$pr['print_type']]??'Impressão') ?></td><td><?= Security::e($pr['user_name']??'Sistema') ?></td><td><?= Security::e($pr['reason']??'—') ?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section></details>
<?php em_footer();